def backfill_plan_and_product(apps, schema_editor):
    """Rows from 0001 have the plan on each line only: copy it up to the
    subscription, and fill line.product from the plan's product."""
    Subscription = apps.get_model("subscriptions", "Subscription")
    SubscriptionLine = apps.get_model("subscriptions", "SubscriptionLine")
    for line in SubscriptionLine.objects.filter(product__isnull=True).select_related("plan"):
        if line.plan.product_id:
            line.product_id = line.plan.product_id
            line.save(update_fields=["product"])
    for sub in Subscription.objects.filter(plan__isnull=True):
        first = SubscriptionLine.objects.filter(subscription=sub).order_by("id").first()
        if first:
            sub.plan_id = first.plan_id
            sub.save(update_fields=["plan"])


